65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "household_size")
85	    private Integer householdSize;
