97	    private Set<Pet> pets;
98	
99	    /**
100	     * Default the registration date to the server's current date when none was
101	     * supplied, then roll the effective date forward onto a business day so a
102	     * weekend registration date always lands on the following Monday. Runs only
103	     * on insert.
104	     */
105	    @PrePersist
106	    private void defaultRegistrationDate() {
107	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
108	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
109	    }
