171	    public void setPostcode(String postcode) {
172	        this.postcode = postcode;
173	    }
174	
175	    public LocalDate getRegistrationDate() {
176	        return this.registrationDate;
177	    }
178	
179	    public void setRegistrationDate(LocalDate registrationDate) {
180	        this.registrationDate = registrationDate;
181	    }
182	
183	    public LocalDate getBirthDate() {
184	        return this.birthDate;
185	    }
186	
187	    public void setBirthDate(LocalDate birthDate) {
188	        this.birthDate = birthDate;
189	    }
190	
191	    public String getCustomerCode() {
192	        return this.customerCode;
193	    }
194	
195	    public void setCustomerCode(String customerCode) {
196	        this.customerCode = customerCode;
197	    }
