229	    }
230	
231	    public Integer getPossibleDuplicateOf() {
232	        return this.possibleDuplicateOf;
233	    }
234	
235	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
236	        this.possibleDuplicateOf = possibleDuplicateOf;
237	    }
238	
239	    /**
240	     * Return whether this owner has been soft-deleted. A newly created owner is not deleted; a
241	     * {@code DELETE /api/owners/{id}} flags the owner deleted while retaining its record.
242	     */
243	    public boolean isDeleted() {
244	        return this.deleted;
245	    }
246	
247	    public void setDeleted(boolean deleted) {
248	        this.deleted = deleted;
249	    }
250	
251	    /**
252	     * Return whether this owner is a possible duplicate: true when it was created while an existing
253	     * owner already shared its last name and postcode under a different telephone, i.e. when a
254	     * {@link #getPossibleDuplicateOf() possible-duplicate-of} owner id is present.
255	     */
256	    @Transient
257	    public boolean getPossibleDuplicate() {
258	        return this.possibleDuplicateOf != null;
259	    }
260	
261	    /**
262	     * Return this owner's name formatted as {@code LastName, FirstName}.
263	     */
264	    @Transient
265	    public String getDisplayName() {
266	        return this.getLastName() + ", " + this.getFirstName();
267	    }
268	
269	    /**
270	     * Return this owner's salutation: the {@link #getTitle() title} followed by a space and the
271	     * last name (e.g. {@code DR Franklin}), or just the last name when no title was supplied.
272	     */
273	    @Transient
274	    public String getSalutation() {
275	        if (this.title == null || this.title.isBlank()) {
276	            return this.getLastName();
277	        }
278	        return this.title + " " + this.getLastName();
279	    }
280	
281	    /**
282	     * Return this owner's telephone formatted for human display: the country code, a space, then
283	     * the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The raw
284	     * {@link #getTelephone() telephone} remains in canonical E.164 form.
285	     */
286	    @Transient
287	    public String getTelephoneDisplay() {
288	        return TelephoneFormatter.format(this.telephone);
289	    }
290	
291	    /**
292	     * Return this owner's identity key: the derived value formed as
293	     * {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or household id
294	     * contributes an empty segment). Members of the same household share a household id but, having
295	     * different telephones, still have distinct identity keys. The telephone and email are expected
296	     * to already be in their normalized storage form.
297	     */
298	    @Transient
299	    public String getIdentityKey() {
300	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
301	    }
302	
303	    private static String orEmpty(String value) {
304	        return value == null ? "" : value;
305	    }
306	
307	    /**
308	     * Return this owner's locality: the REGION segment of the owner's
309	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
310	     * When no customer code has been assigned yet the region is resolved directly from the
311	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
312	     */
313	    @Transient
314	    public String getLocality() {
315	        if (this.customerCode != null && !this.customerCode.isBlank()) {
316	            return CustomerCodeGenerator.regionOf(this.customerCode);
317	        }
318	        return RegionResolver.regionFor(this.postcode, this.city);
319	    }
320	
321	    /**
322	     * Return this owner's timezone: the IANA name mapped from the owner's
323	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table. Null when the
324	     * region has no known timezone.
325	     */
326	    @Transient
327	    public String getTimezone() {
328	        return RegionTimezones.timezoneOf(getLocality());
329	    }
330	
331	    /**
332	     * Return this owner's membership points: starting at 0, plus 2 when the owner has an email,
333	     * plus 1 when the owner is uniquely named (a {@link #getNamesakeCount() namesakeCount} of 0),
334	     * plus 2 for a household of three or more ({@link #getHouseholdSize() household size}), plus 3
335	     * for long tenure ({@link #getTenureFiscalYears() tenure} of more than one fiscal year).
336	     */
337	    @Transient
338	    public int getMembershipPoints() {
339	        boolean hasEmail = this.email != null && !this.email.isEmpty();
340	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
341	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
342	        boolean longTenure = getTenureFiscalYears() > 1;
343	        return MembershipPoints.of(hasEmail, uniquelyNamed, largeHousehold, longTenure);
344	    }
345	
346	    /**
347	     * Return this owner's membership level: the band their {@link #getMembershipPoints() membership
348	     * points} fall into — 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
349	     */
350	    @Transient
351	    public int getMembershipLevel() {
352	        return MembershipPoints.levelFor(getMembershipPoints());
353	    }
354	
355	    /**
356	     * Return this owner's fiscal year: the fiscal year of the business-day-adjusted
357	     * {@link #getRegistrationDate() registration date}, formatted {@code FY<YY>}. The fiscal year
358	     * starts on 1 July. Null when no registration date is known.
359	     */
360	    @Transient
361	    public String getFiscalYear() {
362	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
363	    }
364	
365	    /**
366	     * Return this owner's tenure in whole fiscal years: the number of fiscal years elapsed from the
367	     * {@link #getRegistrationDate() registration date} to today, i.e. the count of 1 July
368	     * fiscal-year boundaries crossed. A newly created owner registered in the current fiscal year
369	     * has zero tenure. Zero when no registration date is known.
370	     */
371	    @Transient
372	    public int getTenureFiscalYears() {
373	        if (this.registrationDate == null) {
374	            return 0;
375	        }
376	        return FiscalYear.elapsedBetween(this.registrationDate, LocalDate.now());
377	    }
378	
379	    /**
380	     * Return this owner's check digit: the single Luhn check digit computed over the
381	     * digits of the {@link #getCustomerCode() customer code}.
382	     */
383	    @Transient
384	    public int getCheckDigit() {
385	        return LuhnCheckDigit.of(this.customerCode);
386	    }
387	
388	    /**
389	     * Return this owner's preferred contact channel: {@code EMAIL} when an
390	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
391	     */
392	    @Transient
393	    public String getContactPreference() {
394	        boolean hasEmail = this.email != null && !this.email.isEmpty();
395	        return hasEmail ? "EMAIL" : "PHONE";
396	    }
397	
398	    /**
399	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
400	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
401	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
402	     */
403	    @Transient
404	    public String getAgeBand() {
405	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
406	        return ageBand == null ? null : ageBand.name();
407	    }
